def solve(inputs: dict) -> float:
    A=int(inputs['A']); B=int(inputs['B']); C=int(inputs['C']); D=int(inputs['D'])
    MOD=int(inputs['MOD']); K=int(inputs['K'])
    def mul(X,Y):
        return [[(X[0][0]*Y[0][0]+X[0][1]*Y[1][0])%MOD,(X[0][0]*Y[0][1]+X[0][1]*Y[1][1])%MOD],
                [(X[1][0]*Y[0][0]+X[1][1]*Y[1][0])%MOD,(X[1][0]*Y[0][1]+X[1][1]*Y[1][1])%MOD]]
    R=[[1,0],[0,1]]; base=[[A%MOD,B%MOD],[C%MOD,D%MOD]]; e=K
    while e>0:
        if e&1: R=mul(R,base)
        base=mul(base,base); e>>=1
    return float((R[0][0]+R[0][1]+R[1][0]+R[1][1])%MOD)

