def solve(inputs: dict) -> float:
    X=int(inputs['SEED']); A=int(inputs['A']); B=int(inputs['B']); M=int(inputs['M']); K=int(inputs['K'])
    for _ in range(K):
        X=(A*X+B)%M
    return float(X)

scripts.xorshift:
def solve(inputs: dict) -> float:
    X=int(inputs['X']); A=int(inputs['A']); B=int(inputs['B']); C=int(inputs['C']); K=int(inputs['K'])
    mask=(1<<32)-1
    for _ in range(K):
        X^=(X<<A)&mask; X&=mask
        X^=(X>>B); X&=mask
        X^=(X<<C)&mask; X&=mask
    return float(X)

